#include <vector>
#include <cmath>
#include <cstddef>
#include <omp.h>

struct COOElement {
    size_t row, column;
    double value;
};

/* Solve the sparse linear system Ax=b for x.
   A is a sparse NxN matrix in COO format. x and b are dense vectors with N elements.
   Uses a parallel Jacobi iterative method.
*/
void solveLinearSystem(std::vector<COOElement> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {
    x.assign(N, 0.0);
    if (N == 0) return;

    // Build diagonal and row-wise COO buckets for efficient Jacobi updates.
    std::vector<double> diag(N, 0.0);
    std::vector<std::vector<std::pair<size_t, double>>> rows(N);

    for (const auto& e : A) {
        if (e.row < N && e.column < N) {
            rows[e.row].push_back({e.column, e.value});
            if (e.row == e.column) diag[e.row] += e.value;
        }
    }

    // Guard against zero diagonal entries.
    for (size_t i = 0; i < N; ++i) {
        if (std::abs(diag[i]) < 1e-15) {
            diag[i] = (diag[i] >= 0.0 ? 1e-15 : -1e-15);
        }
    }

    std::vector<double> x_new(N, 0.0);

    const size_t maxIters = 10000;
    const double tol = 1e-10;

    for (size_t iter = 0; iter < maxIters; ++iter) {
        double maxDiff = 0.0;

        #pragma omp parallel for reduction(max:maxDiff)
        for (std::ptrdiff_t i = 0; i < static_cast<std::ptrdiff_t>(N); ++i) {
            double sigma = 0.0;
            for (const auto& cv : rows[static_cast<size_t>(i)]) {
                size_t j = cv.first;
                double aij = cv.second;
                if (j != static_cast<size_t>(i)) {
                    sigma += aij * x[j];
                }
            }

            double bi = (static_cast<size_t>(i) < b.size()) ? b[static_cast<size_t>(i)] : 0.0;
            x_new[static_cast<size_t>(i)] = (bi - sigma) / diag[static_cast<size_t>(i)];

            double d = std::abs(x_new[static_cast<size_t>(i)] - x[static_cast<size_t>(i)]);
            if (d > maxDiff) maxDiff = d;
        }

        x.swap(x_new);

        if (maxDiff < tol) break;
    }
}
